{"workspaces":[{"id":"default","name":"default","apiName":"default"}],"query":"let LiveBlueprints =
    EntraAgentIdentityBlueprints
    | summarize arg_max(_SnapshotTime, *) by id
    | project Value=appId, Label=strcat("[LIVE] ", displayName, " — ", substring(appId, 0, 8));
let SyntheticBlueprints = datatable(Value:string, Label:string)
[
  "00000000-0000-4000-8000-000000000001", "[SAMPLE] Procurement-Agents",
  "00000000-0000-4000-8000-000000000002", "[SAMPLE] Finance-Reconciliation-Agents"
];
union LiveBlueprints, SyntheticBlueprints
| distinct Value, Label
| order by Label asc
| union (datatable(Value:string, Label:string)["*", "All blueprints"])
| distinct Value, Label
| order by Label asc
| where ("{ContentMode}" == "live" and Label startswith "[LIVE") or ("{ContentMode}" == "synthetic" and Label startswith "[SAMPLE]") or Value == "*""}

