{"workspaces":[{"id":"default","name":"default","apiName":"default"}],"query":"let Blueprints =
    EntraAgentIdentityBlueprints
    | summarize arg_max(_SnapshotTime, *) by id
    | project BlueprintAppId=appId;
let AgentUsers =
    EntraAgentUsers
    | summarize arg_max(_SnapshotTime, *) by id
    | project AgentIdentityObjectId=agentIdentitySPID;
let Agents =
    EntraAgentIdentities
    | summarize arg_max(_SnapshotTime, *) by id
    | project AgentIdentityObjectId=id, BlueprintJoinAppId=agentAppId, accountEnabled;
let LinkedAgents = Agents
    | join kind=inner Blueprints on $left.BlueprintJoinAppId == $right.BlueprintAppId
    | summarize dcount(AgentIdentityObjectId);
let AgentsWithUsers = Agents
    | join kind=inner AgentUsers on AgentIdentityObjectId
    | summarize dcount(AgentIdentityObjectId);
union
(Blueprints | summarize Value=dcount(BlueprintAppId) | extend Metric="Blueprints", CoverageMeaning="Current Agent 365 blueprint records"),
(Agents | summarize Value=dcount(AgentIdentityObjectId) | extend Metric="Agent identities", CoverageMeaning="Current Agent Identity records"),
(LinkedAgents | project Value=dcount_AgentIdentityObjectId | extend Metric="Agents linked to a blueprint", CoverageMeaning="agentAppId matched a current blueprint appId"),
(AgentsWithUsers | project Value=dcount_AgentIdentityObjectId | extend Metric="Agents with agent users", CoverageMeaning="At least one EntraAgentUser matched agentIdentitySPID"),
(Agents | summarize Value=dcountif(AgentIdentityObjectId, accountEnabled == false) | extend Metric="Disabled agent identities", CoverageMeaning="Current Agent Identity record is disabled")
| project Metric, Value, CoverageMeaning"}
